use vstd::prelude::*;

verus! {

pub fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> (result: Vec<f64>)
    requires
        // Each chosen row must exist
        forall|i: int|
            0 <= i < indices.len() ==> (indices[i] as int) < choices.len(),
        // Each chosen row must have enough columns to index by i
        forall|i: int|
            0 <= i < indices.len() ==> i < choices[indices[i] as int].len(),
    ensures
        result.len() == indices.len(),
        // Functional correctness: result[i] is taken from the chosen row at column i
        forall|i: int|
            0 <= i < indices.len() ==>
                result[i] == choices[indices[i] as int][i],
{
    let mut result = Vec::with_capacity(indices.len());

    for (i, &idx_u8) in indices.iter().enumerate()
        invariant
            // i is a valid split point over indices
            0 <= i <= indices.len(),
            // result contains exactly the first i outputs
            result.len() == i,
            forall|j: int|
                0 <= j < i ==>
                    result[j] == choices[indices[j] as int][j],
            // carry preconditions through the loop
            forall|k: int|
                0 <= k < indices.len() ==> (indices[k] as int) < choices.len(),
            forall|k: int|
                0 <= k < indices.len() ==> k < choices[indices[k] as int].len(),
    {
        let row = idx_u8 as usize;
        result.push(choices[row][i]);
    }

    result
}

} // verus!

